  const state=()=>persisted[project()]||(persisted[project()]=defaults());
  const currentTab=()=>state().tabs.find(t=>t.id===state().active)||null;
  function task(){return window.SuitePrototype?.task?.() || $('#taskName b')?.textContent.trim() || $('#windowTask')?.textContent.trim() || 'current-task'}
  function taskState(){const p=state();const first=!p.taskDesign;p.taskDesign||={};const key=task();if(!p.taskDesign[key]){const seed=first?p:defaults();p.taskDesign[key]={};['designMode','frame','designTheme','designState','designVersion','compare','comments','brief','artifacts','artifactFilter','artifactSearch','annotations'].forEach(k=>p.taskDesign[key][k]=JSON.parse(JSON.stringify(seed[k]??defaults()[k])));p.taskDesign[key].designHistory=[];}const current=p.taskDesign[key];['kitFilter','kitVariant','publish','publishTarget','releaseNotes','publishHistory','publishRevision'].forEach(k=>{if(!Object.getOwnPropertyDescriptor(current,k))Object.defineProperty(current,k,{get:()=>p[k],set:v=>p[k]=v,configurable:true})});return current;}

  const dialog=document.createElement('dialog');dialog.className='bd-dialog';dialog.id='bdDialog';dialog.setAttribute('aria-labelledby','bdDialogTitle');document.body.append(dialog);
