  dialog.addEventListener('cancel',e=>{e.preventDefault();closeDialog()});
  function labelForms(root){$$('label',root).forEach(label=>{const control=$('input,select,textarea',label);if(!control)return;const name=$('span',label)?.textContent.trim();if(!control.id)control.id='bdControl-'+uid();label.htmlFor=control.id;if(name&&!control.hasAttribute('aria-label'))control.setAttribute('aria-label',name)})}
  function modal(title,body,actions=[],init){if(!dialog.open)returnFocus=document.activeElement;dialog.innerHTML=`<div class="bd-dialog-head"><h2 id="bdDialogTitle">${esc(title)}</h2><span class="bd-grow"></span>${ib('close-dialog','Закрыть','close')}</div><div class="bd-dialog-body">${body}</div><footer class="bd-dialog-foot"><button class="btn soft" data-bd="cancel-dialog">Закрыть</button>${actions.map((a,i)=>`<button class="btn ${a.primary?'primary':'soft'}" data-action="${i}" ${a.disabled?'disabled':''}>${esc(a.label)}</button>`).join('')}</footer>`; $('[data-bd="close-dialog"]',dialog).onclick=closeDialog;$('[data-bd="cancel-dialog"]',dialog).onclick=closeDialog;actions.forEach((a,i)=>$(`[data-action="${i}"]`,dialog).onclick=()=>a.fn(dialog));labelForms(dialog);if(!dialog.open)dialog.showModal();init?.(dialog);labelForms(dialog);}
  function download(name,content,type='text/plain'){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
