  function inspectorMarkup(mode){return `<section class="bd-inspect"><div class="bd-inspect-tabs">${['Console','Network','Elements','Снимки'].map(x=>`<button data-bd="inspect:${x}" class="${mode===x?'active':''}">${x}</button>`).join('')}<span class="bd-grow"></span>${ib('inspect:','Скрыть инструменты','close')}</div><div class="bd-inspect-content">${mode==='Console'?'<pre data-language="log">[info] Демонстрационный журнал — не данные сайта\n[12:04:16] route.changed /checkout\n[warn] request throttled · retry in 1200ms\n[12:04:18] operation.complete · trace demo-001</pre>':mode==='Network'?'<table class="bd-table"><thead><tr><th>Запрос</th><th>Статус</th><th>Время</th></tr></thead><tbody><tr class="bd-clickrow" data-bd="request:checkout"><td>GET /api/checkout</td><td>200</td><td>186 ms</td></tr><tr class="bd-clickrow" data-bd="request:retry"><td>POST /api/confirm</td><td>429 → 200</td><td>1326 ms</td></tr></tbody></table>':mode==='Elements'?'<pre data-language="xml">&lt;main aria-label="Рабочее пространство"&gt;\n  &lt;h2&gt;Всё нужное для работы — рядом.&lt;/h2&gt;\n  &lt;button data-action="result"&gt;Посмотреть результат&lt;/button&gt;\n&lt;/main&gt;</pre><button class="btn soft" data-bd="inspect-highlight">Подсветить кнопку на макете</button>':state().captures.length?state().captures.map(c=>`<button class="btn ghost" data-bd="capture-open:${c.id}">${esc(c.name)} · ${esc(c.size)}</button>`).join(' '):'Снимков пока нет. Нажмите значок камеры.'}</div></section>`}
  function navigate(raw){const text=raw.trim();if(!text)return;let url;try{url=new URL(text.includes('://')?text:'https://'+text);if(!['http:','https:'].includes(url.protocol))throw Error()}catch{return modal('Адрес не распознан','<p>Введите полный адрес HTTP или HTTPS. В макете внешние страницы не загружаются.</p>')};const s=state(),same=s.tabs.find(t=>t.url===url.href);if(currentTab())delete currentTab().draftUrl;if(same){delete same.draftUrl;s.active=same.id}else{let t=currentTab();if(!t){t=makeTab(url.hostname,url.href);s.tabs.push(t);s.active=t.id}else{t.url=url.href;t.title=url.hostname;t.history=t.history.slice(0,t.index+1);t.history.push(url.href);t.index=t.history.length-1}}s.pageState='ready';save();renderBrowser();note('Адрес сохранён. Контент — локальная демонстрация, внешняя страница не загружалась.')}
  function newTab(){modal('Новая вкладка','<label><span>Адрес</span><input id="bdNewUrl" placeholder="https://example.com" autofocus></label><p class="bd-muted">Если этот адрес уже открыт, переключимся на существующую вкладку.</p><div class="bd-error" id="bdNewUrlError"></div>',[{label:'Открыть',primary:true,fn:d=>{const value=$('#bdNewUrl',d).value.trim();let url;try{url=new URL(value.includes('://')?value:'https://'+value);if(!['http:','https:'].includes(url.protocol)||!value)throw Error()}catch{$('#bdNewUrlError',d).textContent='Введите адрес HTTP или HTTPS.';return}const s=state(),existing=s.tabs.find(t=>t.url===url.href);if(existing)s.active=existing.id;else{const t=makeTab(url.hostname,url.href);s.tabs.push(t);s.active=t.id}save();closeDialog();renderBrowser()}}],d=>$('#bdNewUrl',d).onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();$('[data-action="0"]',d).click()}})}
  function renameTab(id){const t=state().tabs.find(x=>x.id===id);if(!t)return;modal('Переименовать вкладку',`<label><span>Название</span><input id="bdTabName" value="${esc(t.title)}" maxlength="80"></label>`,[{label:'Сохранить',primary:true,fn:d=>{const v=$('#bdTabName',d).value.trim();if(!v)return;t.title=v;save();closeDialog();renderBrowser()}}])}
  function closeTab(id){const s=state(),index=s.tabs.findIndex(t=>t.id===id);if(index<0)return;const t=s.tabs[index];s.closed.unshift(t);s.closed=s.closed.slice(0,10);s.tabs.splice(index,1);if(s.active===id)s.active=s.tabs[Math.max(0,index-1)]?.id||null;save();renderBrowser()}
  function tabMenu(id){const t=state().tabs.find(x=>x.id===id);if(!t)return;menu(t.title,[{label:'Переименовать',fn:()=>renameTab(id)},{label:t.pinned?'Открепить':'Закрепить',fn:()=>{t.pinned=!t.pinned;save();renderBrowser()}},{label:'Закрыть вкладку',fn:()=>closeTab(id)},{label:'Закрыть другие',hint:'Закреплённые вкладки сохранятся',fn:()=>{state().tabs.filter(x=>x.id!==id&&!x.pinned).forEach(x=>closeTab(x.id));state().active=id;save();renderBrowser()}}])}
  function devices(){const s=state();modal('Размер страницы',`<label><span>Устройство</span><select id="bdDevice"><option value="auto">По ширине панели</option><option value="390,844">Телефон · 390 × 844</option><option value="768,1024">Планшет · 768 × 1024</option><option value="1440,900">Desktop · 1440 × 900</option><option value="custom">Свой размер</option></select></label><div class="bd-row"><label class="bd-grow"><span>Ширина, px</span><input id="bdWidth" type="number" min="240" max="3840" value="${s.width==='auto'?1440:s.width}"></label><label class="bd-grow"><span>Высота, px</span><input id="bdHeight" type="number" min="240" max="3840" value="${s.height}"></label><button class="btn soft" id="bdRotate">Повернуть</button></div><label><span>Масштаб</span><select id="bdZoom">${[50,75,90,100,125,150].map(z=>`<option ${s.zoom===z?'selected':''}>${z}</option>`).join('')}</select></label><p class="bd-muted">Меняется размер локального макета. Эмуляция touch, DPR, user-agent и настоящий device viewport требуют подключения браузера в приложении.</p><div id="bdDeviceError" class="bd-error"></div>`,[{label:'Применить',primary:true,fn:d=>{const w=+$('#bdWidth',d).value,h=+$('#bdHeight',d).value;if(!Number.isInteger(w)||!Number.isInteger(h)||w<240||h<240||w>3840||h>3840){$('#bdDeviceError',d).textContent='Размер должен быть от 240 до 3840 px.';return}s.width=$('#bdDevice',d).value==='auto'?'auto':w;s.height=h;s.zoom=+$('#bdZoom',d).value;save();closeDialog();renderBrowser()}}],d=>{$('#bdDevice',d).value=s.width==='auto'?'auto':'custom';$('#bdDevice',d).onchange=e=>{if(e.target.value.includes(',')){const [w,h]=e.target.value.split(',');$('#bdWidth',d).value=w;$('#bdHeight',d).value=h}};$('#bdRotate',d).onclick=()=>{const w=$('#bdWidth',d),h=$('#bdHeight',d);[w.value,h.value]=[h.value,w.value];$('#bdDevice',d).value='custom'}})}
  function captureSvg(c){return `<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="600" viewBox="0 0 1000 600"><rect width="1000" height="600" fill="#f5f6f4"/><text x="44" y="50" font-family="Arial" font-size="24" fill="#344c3b">atlas.</text><path d="M0 78h1000" stroke="#dce0da"/><text x="55" y="140" font-family="Arial" font-size="12" fill="#687368">PROTOTYPE · ORIGINAL ILLUSTRATION</text><text x="55" y="205" font-family="Arial" font-size="32" fill="#242824">Всё нужное для работы — рядом.</text><text x="55" y="250" font-family="Arial" font-size="16" fill="#667064">${esc(c.name)}</text><rect x="55" y="284" width="200" height="42" rx="7" fill="#344c3b"/><text x="78" y="312" font-family="Arial" font-size="14" fill="white">Посмотреть результат</text>${[55,355,655].map((x,i)=>`<rect x="${x}" y="366" width="275" height="124" rx="10" fill="white" stroke="#dde2da"/><text x="${x+20}" y="405" font-family="Arial" font-size="16" fill="#344c3b">${['Результат','Изменения','Следующий шаг'][i]}</text>`).join('')}<text x="55" y="555" font-family="Arial" font-size="12" fill="#667064">Illustrative capture · ${esc(c.size)} · no external page captured</text></svg>`}
  function createCapture(){const s=state(),c={id:uid(),name:(currentTab()?.title||'Макет')+' · '+new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}),size:s.width==='auto'?'По ширине панели':s.width+' × '+s.height,url:currentTab()?.url};s.captures.unshift(c);save();openCapture(c.id)}
  function openCapture(id){const c=state().captures.find(x=>x.id===id);if(!c)return;modal('Снимок макета',`<div class="bd-screen-art">${captureSvg(c)}</div><p class="bd-muted">Иллюстрация снимка для проверки UX. Настоящий screenshot удалённой страницы в этом HTML недоступен.</p><p>${esc(c.url||'')}</p>`,[{label:'Сравнить',fn:()=>compareCaptures(c.id)},{label:'В материалы',fn:()=>{taskState().artifacts.unshift({id:uid(),title:c.name,type:'SVG',version:1,archived:false,captureId:c.id});save();closeDialog();note('Иллюстрация сохранена в материалы текущего проекта.')}},{label:'Скачать SVG',primary:true,fn:()=>download('prototype-capture.svg',captureSvg(c),'image/svg+xml')}])}
  function compareCaptures(id){const s=state(),a=s.captures.find(x=>x.id===id);if(!a)return;const candidates=s.captures.filter(x=>x.id!==id);if(!candidates.length)return modal('Сравнение снимков','<p>Нужны два снимка. Закройте диалог и сделайте ещё один снимок кнопкой камеры.</p>');let b=candidates[0];modal('Сравнение снимков',`<label><span>Сравнить с</span><select id="bdCompareCapture">${candidates.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><div class="bd-compare" id="bdCapturePair"></div><p class="bd-muted">Иллюстрации для сравнения UX. Pixel diff и реальные изменения страницы здесь не рассчитываются.</p>`,[{label:'Передать агенту',primary:true,fn:()=>{closeDialog();ask('Сравни снимки «'+a.name+'» и «'+b.name+'». Это демонстрационные материалы; не считай их доказательством работы реального сайта.')}}],d=>{const draw=()=>$('#bdCapturePair',d).innerHTML=[a,b].map(c=>`<div><b>${esc(c.name)}</b><div class="bd-screen-art">${captureSvg(c)}</div><small>${esc(c.size)}</small></div>`).join('');$('#bdCompareCapture',d).onchange=e=>{b=s.captures.find(c=>c.id===e.target.value);draw()};draw()})}
  function agentBrowser(){window.SuiteAgentBrowser?.prepare(currentTab()?.url||'');}
  function openUserURL(raw){
    let url;try{url=new URL(raw);if(!['https:','http:'].includes(url.protocol)||url.username||url.password)throw Error();}catch{return false;}
    const s=state(),existing=s.tabs.find(t=>t.url===url.href);
    if(existing)s.active=existing.id;else{const t=makeTab(url.hostname,url.href);s.tabs.push(t);s.active=t.id;}
    save();renderBrowser();window.SuiteWorkspaceLayout?.open('browser');return true;
  }
  browser.addEventListener('click',e=>{const action=e.target.closest('[data-bd]')?.dataset.bd;if(!action)return;const s=state(),tab=currentTab();
    if(action.startsWith('close-tab:'))return closeTab(action.split(':')[1]);
    if(action.startsWith('inspect:')){s.inspector=action.slice(8);save();return renderBrowser()}
    if(action.startsWith('capture-open:'))return openCapture(action.slice(13));
    if(action.startsWith('request:')){const throttled=action==='request:retry',request=throttled?'POST /api/confirm HTTP/1.1\nContent-Type: application/json\nX-Request-ID: demo-001':'GET /api/checkout HTTP/1.1\nAccept: application/json\nX-Request-ID: demo-002',response=throttled?'HTTP/1.1 429 Too Many Requests\nContent-Type: text/html\nRetry-After: 1':'HTTP/1.1 200 OK\nContent-Type: application/json',body=throttled?'<!doctype html>\n<html><body><h1>Too many requests</h1><p>Retry in 1 second.</p></body></html>':JSON.stringify({orderId:'100248',status:'ready'},null,2);return modal('Сведения о запросе',`<span class="bd-chip">Fixture · без реального HTTP</span><h3>Запрос</h3><pre data-language="http">${esc(request)}</pre>${throttled?'<h3>Тело запроса</h3><pre data-language="json">'+esc(JSON.stringify({orderId:'100248',idempotencyKey:'demo-only-001'},null,2))+'</pre>':''}<h3>Ответ</h3><pre data-language="http">${esc(response)}</pre><pre data-language="${throttled?'html':'json'}">${esc(body)}</pre>${throttled?'<h3>Нормализованная ошибка</h3><pre data-language="json">'+esc(JSON.stringify({status:429,kind:'rate_limit',retryAfterMs:1000,contentType:'text/html',requestId:'demo-001',executed:false},null,2))+'</pre>':''}<p class="bd-muted">${throttled?'Следующая попытка в fixture: 200 · всего 1326 ms.':'Fixture: 200 · 186 ms.'} HTML показан как безопасный текст и не исполняется. В приложении здесь доступны заголовки, тело с редактированием чувствительных данных, timing, initiator и связь с действием агента.</p>`);}
    if(action==='new-tab')return newTab();
    if(action==='back'||action==='forward'){if(!tab)return;tab.index+=action==='back'?-1:1;tab.index=Math.max(0,Math.min(tab.history.length-1,tab.index));tab.url=tab.history[tab.index];delete tab.draftUrl;save();return renderBrowser()}
    if(action==='reload'){if(!tab)return;delete tab.draftUrl;s.pageState='loading';renderBrowser();setTimeout(()=>{s.pageState='ready';save();renderBrowser()},500);return}
    if(action==='debugger'){if(s.inspector&&s.inspector!=='Снимки'){s.inspector='';save();renderBrowser();$('[data-bd="debugger"]',browser)?.focus();return}return browserTools?.openDebugger();}
    if(action==='bookmark')return browserTools?.openBookmarks(true);
    if(action==='devices')return devices();
    if(action==='browser-profile')return profileDialog();
    if(action==='capture')return createCapture();
    if(action==='expand')return window.SuiteWorkspaceLayout?window.SuiteWorkspaceLayout.maximize('browser'):$('#chatVisibility')?.click();
    if(action==='external')return modal('Открыть во внешнем браузере',`<p>${esc(tab?.url||'Адрес не выбран')}</p><p class="bd-muted">В desktop-приложении адрес откроется в браузере по умолчанию. Здесь доступна только демонстрация: системный браузер из макета не запускается.</p>`,[{label:'Скопировать адрес',fn:()=>{navigator.clipboard?.writeText(tab?.url||'').then(()=>note('Адрес скопирован')).catch(()=>note('Выделите адрес и скопируйте вручную'))}}]);
    if(action==='site-info')return modal('Подключение страницы',`<p><b>${esc(s.profile)}</b></p><p>Текущий проект: ${esc(project())}</p><p class="bd-muted">Макет не устанавливает TLS-соединение и не проверяет сертификаты.</p><div class="bd-box"><b>В итоговом приложении</b><p>Состояние сертификата и цепочка доверия, выбор клиентского сертификата, доступные browser profiles, cookies и разрешения сайта. Доступ к корпоративному профилю проверяется на рабочем компьютере.</p></div>`,[{label:'Cookies и данные сайта',fn:()=>browserTools?.openSiteData()},{label:'Профиль',fn:()=>profileDialog()}]);
    if(action==='show-agent-browser')return window.SuiteAgentBrowser?.open();
    if(action==='browser-agent')return agentBrowser();
    if(action==='page-primary'){s.pageState=s.pageState==='success'?'ready':'success';save();return renderBrowser()}
    if(action==='page-secondary')return modal('Подробности результата','<p>Демонстрационный заказ <b>#100248</b></p><dl><dt>Состояние</dt><dd>Подтверждён</dd><dt>Следующее действие</dt><dd>Открыть карточку заказа</dd></dl>');
    if(action==='inspect-highlight'){const el=$('[data-bd="page-primary"]',browser);if(el){el.style.outline='3px solid #769dd6';setTimeout(()=>el.style.outline='',1700)}return}
    if(action==='browser-menu')return menu('Браузер',[
      {label:'Инструменты разработчика',hint:'Sources, Console, Network, Elements, Performance',fn:()=>browserTools?.openDebugger()},
      {label:'Закладки',hint:'Папки, поиск и сохранённые страницы',fn:()=>browserTools?browserTools.openBookmarks():bookmarksDialog()},
      {label:browserTools?.state().settings.bookmarkBar===false?'Показать панель закладок':'Скрыть панель закладок',hint:'Ctrl / Cmd + Shift + B',fn:()=>bookmarkBar?.toggle()},
      {label:'История и закрытые вкладки',fn:()=>historyDialog()},
      {label:'Загрузки',fn:()=>downloadsDialog()},
      {label:'Пароли и автозаполнение',fn:()=>browserTools?.openPasswords()},
      {label:'Cookies и кэш',hint:'Данные сайтов выбранного профиля',fn:()=>browserTools?.openSiteData()},
      {label:'Настройки браузера',fn:()=>browserTools?.openSettings()},
      {label:'Дополнительно',hint:'Поиск, снимки, печать, профиль и восстановление',fn:()=>menu('Дополнительно',[
        {label:'Снимки',hint:s.captures.length+' сохранено в этом проекте',fn:()=>{s.inspector='Снимки';renderBrowser()}},
        {label:'Найти на странице',fn:()=>findInPage()},
        {label:'Печать / PDF',fn:()=>printDialog()},
        {label:'Профиль браузера',hint:s.profile,fn:()=>profileDialog()},
        {label:'Восстановление после сбоя',hint:'Проверить сценарий переподключения',fn:()=>browserRecovery()},
        {label:'Состояния страницы',hint:'Успех, загрузка, ошибка, offline',fn:()=>menu('Состояние макета',['ready','loading','empty','error','offline'].map((x,i)=>({label:['Обычный экран','Загрузка','Пустое состояние','Ошибка','Нет соединения'][i],fn:()=>{s.pageState=x;save();renderBrowser()}})))},
        {label:'Открыть во внешнем браузере',fn:()=>$('[data-bd="external"]',browser).click()},
        {label:'Управление агентом',fn:agentBrowser}
      ])}
    ]);
  });
  function historyDialog(){const s=state();modal('История браузера',`<h3>Текущая вкладка</h3><div class="bd-menu-list">${(currentTab()?.history||[]).map((url,i)=>`<button data-history="${i}">${esc(url)}</button>`).join('')||'<p class="bd-muted">История пуста.</p>'}</div><h3>Недавно закрытые</h3><div class="bd-menu-list">${s.closed.map((t,i)=>`<button data-reopen="${i}">${esc(t.title)}<small>${esc(t.url)}</small></button>`).join('')||'<p class="bd-muted">Закрытых вкладок нет.</p>'}</div>`,[],d=>{$$('[data-history]',d).forEach(b=>b.onclick=()=>{currentTab().index=+b.dataset.history;currentTab().url=currentTab().history[currentTab().index];save();closeDialog();renderBrowser()});$$('[data-reopen]',d).forEach(b=>b.onclick=()=>{const t=s.closed.splice(+b.dataset.reopen,1)[0];const already=s.tabs.find(x=>x.url===t.url);if(already)s.active=already.id;else{s.tabs.push(t);s.active=t.id}save();closeDialog();renderBrowser()})})}
  function bookmarksDialog(){const s=state();modal('Закладки',`<div class="bd-menu-list">${s.bookmarks.map((b,i)=>`<div class="bd-row"><button data-bookmark="${i}" class="bd-grow">${esc(b.title)}<small>${esc(b.url)}</small></button><button data-remove-bookmark="${i}" aria-label="Удалить закладку ${esc(b.title)}">×</button></div>`).join('')||'<p class="bd-muted">Пока нет закладок.</p>'}</div>`,[{label:'Добавить текущую',disabled:!currentTab(),primary:true,fn:()=>{const t=currentTab();if(!s.bookmarks.some(b=>b.url===t.url))s.bookmarks.push({title:t.title,url:t.url});save();bookmarksDialog()}}],d=>{$$('[data-bookmark]',d).forEach(b=>b.onclick=()=>{const mark=s.bookmarks[+b.dataset.bookmark];closeDialog();navigate(mark.url)});$$('[data-remove-bookmark]',d).forEach(b=>b.onclick=()=>{s.bookmarks.splice(+b.dataset.removeBookmark,1);save();bookmarksDialog()})})}
  function profileDialog(){const s=state();modal('Профиль браузера',`<label><span>Профиль текущего проекта</span><select id="bdProfile"><option ${s.profile==='Изолированный'?'selected':''}>Изолированный</option><option ${s.profile==='Корпоративный'?'selected':''}>Корпоративный</option></select></label><p class="bd-muted">В макете меняется выбранный профиль, без переноса cookies, сертификатов и авторизации. В приложении проверяется доступ к корпоративному профилю; автоматический доступ ко всем данным другого браузера не обещается.</p>`,[{label:'Применить',primary:true,fn:d=>{s.profile=$('#bdProfile',d).value;save();closeDialog();renderBrowser()}}])}

  function browserRecovery(){const s=state();modal('Браузер не отвечает',`<p>Связь с процессом браузера потеряна. Сохранены <b>${s.tabs.length} вкладки</b> и активная вкладка <b>${esc(currentTab()?.title||'не выбрана')}</b>.</p><div class="bd-note">Демонстрация восстановления. Сохранённые адреса не подтверждают состояние форм, авторизации или незавершённых внешних действий.</div><label class="bd-inline-label"><input type="checkbox" id="bdRestoreAll" checked>Восстановить все вкладки</label><p class="bd-muted">В runtime сначала переподключение и сверка текущего состояния. Не отправлять незавершённые формы повторно.</p>`,[{label:'Восстановить',primary:true,fn:d=>{if(!$('#bdRestoreAll',d).checked&&currentTab()){const active=currentTab();s.closed.unshift(...s.tabs.filter(x=>x.id!==active.id));s.tabs=[active]}s.pageState='loading';save();closeDialog();renderBrowser();setTimeout(()=>{s.pageState='ready';save();renderBrowser();note('Демонстрация восстановления завершена. Активная вкладка сохранена.')},650)}}])}
  function findInPage(){modal('Найти на странице','<label><span>Текст</span><input id="bdFindText" placeholder="Что найти"></label><div class="bd-muted" id="bdFindResult"></div>',[{label:'Найти',primary:true,fn:d=>{const text=$('#bdFindText',d).value.trim().toLowerCase();const matches=$$('h2,p,b,small,button',$('#bdViewport')).filter(el=>text&&el.textContent.toLowerCase().includes(text));$$('.bd-found',browser).forEach(el=>{el.classList.remove('bd-found');el.style.outline=''});matches.forEach(el=>{el.classList.add('bd-found');el.style.outline='2px solid var(--amber)'});$('#bdFindResult',d).textContent=matches.length?'Найдено элементов: '+matches.length:'Совпадений нет';matches[0]?.scrollIntoView({block:'center'})}}],d=>$('#bdFindText',d).onkeydown=e=>{if(e.key==='Enter')$('[data-action="0"]',d).click()})}
  function downloadsDialog(){closeDialog();downloadWorkbench?.open()}
  function printDialog(){modal('Печать / PDF','<label><span>Назначение</span><select><option>Сохранить как PDF</option><option>Системный принтер</option></select></label><div class="bd-row"><label class="bd-grow"><span>Ориентация</span><select><option>Книжная</option><option>Альбомная</option></select></label><label class="bd-grow"><span>Страницы</span><input value="Все"></label></div><label class="bd-inline-label"><input type="checkbox" checked>Фон и изображения</label><div class="bd-note">Целевой диалог desktop-приложения. В этом макете PDF-движок не подключён, поэтому готовый PDF не выдаётся.</div>',[{label:'Печать недоступна в макете',disabled:true}])}

  const designPanel=$('[data-panel="design"]');
  $$('.view-toolbar,.design-body',designPanel).forEach(x=>x.classList.add('bd-legacy'));
  const design=document.createElement('div');design.className='bd-root';design.id='bdDesign';designPanel.append(design);
  const modes={canvas:'Макеты',artifacts:'Материалы',kit:'UI Kit',publish:'Публикация'};
  function renderDesign(){const s=taskState();design.innerHTML=`<div class="bd-designbar"><h2>Design & Artifacts</h2><div class="bd-modebar" role="tablist" aria-label="Дизайн и материалы">${Object.entries(modes).map(([key,label])=>`<button role="tab" aria-selected="${s.designMode===key}" class="${s.designMode===key?'active':''}" data-bd="mode:${key}">${label}</button>`).join('')}</div><span class="bd-chip">Интерактивный макет</span>${ib('design-agent','Поручить текущий материал агенту','spark')}</div><div class="bd-design-content">${s.designMode==='canvas'?canvasMarkup():s.designMode==='artifacts'?artifactsMarkup():s.designMode==='kit'?kitMarkup():publishMarkup()}</div>`;bindDesignInputs()}
  function canvasMarkup(){const s=taskState();return `<div class="bd-content-toolbar"><div class="bd-grow"><h2 class="bd-title">Завершение заказа</h2><span class="bd-muted">v${s.designVersion} · изменения сохранены локально</span></div><button class="btn soft" data-bd="design-version">Версии</button><button class="btn soft" data-bd="design-play">Предпросмотр</button><button class="btn primary" data-bd="design-export">Экспорт</button></div><div class="bd-design-grid"><div><div class="bd-content-toolbar"><select id="bdFrame" aria-label="Размер макета"><option value="desktop" ${s.frame==='desktop'?'selected':''}>Desktop · 1440</option><option value="tablet" ${s.frame==='tablet'?'selected':''}>Tablet · 768</option><option value="mobile" ${s.frame==='mobile'?'selected':''}>Mobile · 390</option></select><select id="bdTheme" aria-label="Тема макета"><option value="light" ${s.designTheme==='light'?'selected':''}>Светлая</option><option value="dark" ${s.designTheme==='dark'?'selected':''}>Тёмная</option></select><select id="bdDesignState" aria-label="Состояние макета">${Object.entries({success:'Успех',loading:'Загрузка',empty:'Пусто',error:'Ошибка',offline:'Нет сети',long:'Длинный текст'}).map(([v,l])=>`<option value="${v}" ${s.designState===v?'selected':''}>${l}</option>`).join('')}</select><span class="bd-grow"></span><button class="btn ghost" data-bd="design-compare" aria-pressed="${s.compare}">Сравнить</button></div>${s.compare?'<div class="bd-compare" style="margin-bottom:12px"><div><b>v6</b><p>Квитанция скрыта в дополнительном меню. Основная кнопка 36 px.</p></div><div><b>v7</b><p>Квитанция в карточке результата. Основная кнопка 44 px.</p></div></div>':''}<div class="bd-canvas"><div class="bd-artboard bd-viewport ${s.designTheme==='dark'?'dark':''} ${s.frame==='mobile'?'mobile':''}" style="max-width:${s.frame==='mobile'?390:s.frame==='tablet'?600:740}px;min-height:360px">${pageMarkup(s.designState,true)}</div><p class="bd-canvas-caption">${s.frame==='desktop'?'1440 × 900':s.frame==='tablet'?'768 × 1024':'390 × 844'} · масштабированная композиция · ${s.designTheme==='dark'?'тёмная':'светлая'} тема</p></div></div><aside class="bd-stack"><section class="bd-box"><h3>Задание</h3><p class="bd-muted">${esc(s.brief)}</p><button class="btn ghost" data-bd="brief-edit">Изменить</button></section><section class="bd-box"><h3>Проверка качества</h3><p class="bd-muted">Контраст, клавиатура, размеры и состояния. Итоговый балл без измерений не выставляется.</p><button class="btn soft" data-bd="design-audit">Проверить макет</button></section><section class="bd-box"><div class="bd-row"><h3 class="bd-grow">Комментарии · ${s.comments.filter(c=>!c.resolved).length}</h3>${ib('comment-add','Добавить комментарий','plus')}</div>${s.comments.slice(-3).map(c=>`<div class="bd-comment" style="opacity:${c.resolved?.5:1}">${esc(c.text)}<br><button class="btn ghost" data-bd="comment-resolve:${c.id}">${c.resolved?'Вернуть':'Решено'}</button></div>`).join('')}</section></aside></div>`}
  function artifactsMarkup(){const s=taskState(),list=s.artifacts.filter(a=>(s.artifactFilter==='archive'?a.archived:!a.archived)&&(s.artifactFilter==='all'||s.artifactFilter==='archive'||a.type===s.artifactFilter)&&a.title.toLowerCase().includes(s.artifactSearch.toLowerCase()));return `<div class="bd-content-toolbar"><div class="bd-grow"><h2 class="bd-title">Материалы задачи</h2><span class="bd-muted">${esc(task())} · открыть, обсудить и передать результат</span></div><button class="btn primary" data-bd="artifact-new">Создать</button></div><div class="bd-content-toolbar"><input class="bd-grow" id="bdArtifactSearch" placeholder="Найти материал…" aria-label="Поиск материалов" value="${esc(s.artifactSearch)}"><select id="bdArtifactFilter" aria-label="Тип материалов">${Object.entries({all:'Все материалы',HTML:'Макеты',Markdown:'Тексты',Document:'Документы',SVG:'Изображения',archive:'Архив'}).map(([v,l])=>`<option value="${v}" ${s.artifactFilter===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="bd-cardgrid">${list.map(a=>`<article class="bd-box bd-material"><div class="bd-material-preview">${a.type==='HTML'?ic('code'):a.type==='SVG'?ic('camera'):ic('edit')}</div><b>${esc(a.title)}</b><span class="bd-muted">${esc(a.type)} · v${a.version} · ${a.archived?'в архиве':'текущая задача'}</span><div class="bd-row"><button class="btn soft" data-bd="artifact-open:${a.id}">Открыть</button><span class="bd-grow"></span>${ib('artifact-menu:'+a.id,'Действия с материалом '+a.title,'more')}</div></article>`).join('')||'<div class="bd-empty">Материалов не найдено. Измените фильтр или создайте новый.</div>'}</div>`}
  const components=[['button','Кнопка','Action','<span class="btn primary">Продолжить</span>'],['field','Поле ввода','Form','<span class="bd-sample-field">Название проекта</span>'],['select','Выбор значения','Form','<span class="bd-sample-field">ДЕВ <span style="float:right">⌄</span></span>'],['status','Статус','Feedback','<span class="bd-chip">✓ Выполнено</span>'],['tabs','Вкладки','Navigation','<span class="bd-chip">Обзор</span> <span style="padding:7px">История</span>'],['table','Таблица','Data','<span class="bd-sample-field">Имя &nbsp; Статус &nbsp; Изменён<br>api &nbsp; Ready &nbsp; Сейчас</span>'],['empty','Пустое состояние','Feedback','<span>Нет данных · Создать</span>'],['question','Вопрос агентa','Agent','<span class="bd-chip">Вариант А</span> <span style="padding:7px">Свой ответ</span>'],['plan','План агента','Agent','<span>✓ Анализ &nbsp; ◉ Проверка</span>'],['progress','Ход операции','Feedback','<span style="width:90%;height:4px;background:var(--line)"><i style="display:block;width:65%;height:4px;background:var(--mint)"></i></span>'],['dialog','Диалог','Overlay','<span class="bd-sample-field">Изменения готовы &nbsp; ×</span>'],['token','Токены','Foundation','<span style="display:flex;gap:5px"><i style="width:24px;height:24px;background:var(--mint);border-radius:5px"></i><i style="width:24px;height:24px;background:var(--blue);border-radius:5px"></i></span>']];
  function kitMarkup(){const s=taskState(),list=components.filter(c=>(c[1]+' '+c[2]).toLowerCase().includes(s.kitFilter.toLowerCase()));return `<div class="bd-content-toolbar"><div class="bd-grow"><h2 class="bd-title">Корпоративный UI Kit</h2><span class="bd-muted">Оригинальные компоненты · семантические токены · контракты состояний</span></div><button class="btn soft" data-bd="kit-icons">Иконки</button><button class="btn soft" data-bd="kit-templates">Шаблоны</button></div><div class="bd-note">Каталог показывает целевой UX компонентов. Готовность исходников отслеживается отдельно в ui-kit/: наличие превью не означает готовую библиотеку.</div><div class="bd-content-toolbar bd-spaced"><input id="bdKitSearch" class="bd-grow" value="${esc(s.kitFilter)}" placeholder="Найти компонент или категорию…" aria-label="Поиск компонентов"><button class="btn ghost" data-bd="kit-tokens">Токены и темы</button></div><div class="bd-component-grid">${list.map(c=>`<button class="bd-component" data-bd="component:${c[0]}"><b>${c[1]}</b><span class="bd-muted">${c[2]}</span><div class="bd-component-demo">${c[3]}</div></button>`).join('')||'<p class="bd-muted">Компоненты не найдены.</p>'}</div>`}
  function kitConnections(){const registry=window.SuitePrototype?.connections?.();if(Array.isArray(registry))return registry.filter(c=>['UI Kit','Bitbucket'].includes(c.type)&&(!Array.isArray(c.projects)||c.projects.includes(project()))).sort((a,b)=>(a.type==='UI Kit'?0:1)-(b.type==='UI Kit'?0:1));return [{id:'demo-ui-kit',type:'UI Kit',name:'Design Systems · демонстрация',address:'https://example.invalid/mcp/ui-kit',projects:[project()]}]}
  function kitConnection(id){return kitConnections().find(c=>c.id===id)}
  function publishSnapshot(){const s=taskState(),target=s.publishTarget||{},connection=kitConnection(target.connectionId)||(!target.connectionId?kitConnections()[0]:null);return {connectionId:connection?.id||target.connectionId||'',connection:connection?.name||target.connection||'Подключение не выбрано',address:connection?.address||'',project:project(),repo:target.repo||'corp-ui/enterprise-kit',package:target.package||'@corp/ui-kit',channel:target.channel||'canary'}}
  function publishMarkup(){const s=taskState(),target=s.publish!=='draft'&&s.publishHistory?.[0]?.target?s.publishHistory[0].target:publishSnapshot();return `<div class="bd-content-toolbar"><div class="bd-grow"><h2 class="bd-title">Публикация UI Kit</h2><span class="bd-muted">${esc(target.repo)} · пакет ${esc(target.package)}</span></div><span class="bd-chip">${s.publish==='draft'?'Черновик':s.publish==='review'?'На ревью · демо':'Готов к выпуску · демо'}</span></div><div class="bd-design-grid"><div class="bd-stack"><section class="bd-box"><h3>Изменения версии 0.2.0</h3><table class="bd-table"><thead><tr><th>Файл</th><th>Изменение</th></tr></thead><tbody><tr><td>components/Question.tsx</td><td>Свободный ответ и последовательные вопросы</td></tr><tr><td>tokens/semantic.json</td><td>Состояния фокуса для обеих тем</td></tr><tr><td>icons/browser.svg</td><td>Оригинальная геометрия, 24 × 24</td></tr></tbody></table><button class="btn ghost" data-bd="publish-diff">Посмотреть diff</button></section><section class="bd-box"><h3>Проверки перед передачей</h3><p class="bd-muted">Ниже демонстрационные результаты. Настоящие проверки библиотеки запускаются на реализации.</p><div class="bd-row"><span class="bd-chip">Types · fixture</span><span class="bd-chip">A11y · fixture</span><span class="bd-chip">Provenance · оригинал</span></div><button class="btn soft bd-spaced" data-bd="publish-check">Показать отчёт</button></section></div><aside class="bd-stack"><section class="bd-box"><h3>Назначение</h3><p class="bd-muted">${esc(target.connection)}<br>${esc(target.repo)}<br>${esc(target.package)} · ${esc(target.channel)}</p><button class="btn ghost" data-bd="publish-target">Настроить</button></section><section class="bd-box"><h3>Передача коллегам</h3><p class="bd-muted">Сначала сравнение изменений и ревью, затем версия пакета и changelog.</p><button class="btn primary" data-bd="publish-prepare">${s.publish==='draft'?'Подготовить ревью':'Открыть ревью'}</button><button class="btn ghost" data-bd="publish-export">Скачать handoff</button><button class="btn ghost" data-bd="publish-history">История ревью</button></section></aside></div>`}
  function bindDesignInputs(){const s=taskState();[['#bdFrame','frame'],['#bdTheme','designTheme'],['#bdDesignState','designState'],['#bdArtifactFilter','artifactFilter']].forEach(([selector,key])=>{const x=$(selector,design);if(x)x.onchange=()=>{s[key]=x.value;save();renderDesign()}});[['#bdArtifactSearch','artifactSearch'],['#bdKitSearch','kitFilter']].forEach(([selector,key])=>{const x=$(selector,design);if(x)x.oninput=()=>{const pos=x.selectionStart;s[key]=x.value;save();renderDesign();const next=$(selector,design);next.focus();next.setSelectionRange(pos,pos)}})}
  function editText(title,current,onSave,language='text'){modal(title,`<label><span>Текст</span><textarea id="bdEditText" data-language="${esc(language)}" spellcheck="false">${esc(current)}</textarea></label><div class="bd-error" id="bdEditError"></div>`,[{label:'Сохранить',primary:true,fn:d=>{const text=$('#bdEditText',d).value.trim();if(!text){$('#bdEditError',d).textContent='Введите текст.';return}onSave(text);save();closeDialog();renderDesign()}}])}
  function artifactLanguage(a){const name=String(a.filename||a.path||a.title||'').toLowerCase(),extension=name.match(/\.([a-z0-9]+)$/)?.[1];return ({html:'html',htm:'html',css:'css',js:'javascript',mjs:'javascript',cjs:'javascript',jsx:'jsx',ts:'typescript',tsx:'tsx',svg:'xml',xml:'xml',md:'markdown',mdx:'markdown',json:'json',jsonl:'json',yaml:'yaml',yml:'yaml',diff:'diff',patch:'diff',sql:'sql',py:'python',java:'java',log:'log',http:'http'})[extension]||({HTML:'html',SVG:'xml',Markdown:'markdown',JSON:'json',CSS:'css',JavaScript:'javascript',TypeScript:'typescript',SQL:'sql'})[a.type]||'text'}
  function artifactContent(a){if(a.content)return a.content;if(a.type==='Markdown')return '# '+a.title+'\n\n## Цель\nСделать повторные запросы предсказуемыми и отменяемыми.\n\n## Критерии\n- Нет повторного исполнения при неизвестном исходе.\n- Пользователь видит состояние и следующий шаг.\n- Ошибки HTML нормализуются в читаемый текст.\n\nДемонстрационный документ.';if(a.type==='Document')return a.title+'\n\nРезультаты проверки\n1. Контраст кнопки — рассчитывается по фактическим цветам.\n2. Клавиатура — порядок фокуса проверяется отдельно.\n3. Адаптивность — 390, 768, 1440 px.\n\nЭтот отчёт является демонстрацией формата, не результатом аудита.';return a.title}
  function openArtifact(id){const a=taskState().artifacts.find(x=>x.id===id);if(!a)return;let body=a.type==='HTML'?`<div class="bd-viewport">${pageMarkup('success',true)}</div>`:a.type==='SVG'?`<div class="bd-screen-art">${captureSvg(state().captures.find(c=>c.id===a.captureId)||{name:a.title,size:'1000 × 600'})}</div>`:a.type==='Document'&&artifactLanguage(a)==='text'?`<article class="bd-preview-document"><h2>${esc(a.title)}</h2>${esc(artifactContent(a)).split('\n').map(x=>`<p>${x}</p>`).join('')}</article>`:`<pre data-language="${esc(artifactLanguage(a))}">${esc(artifactContent(a))}</pre>`;modal(a.title,`<div class="bd-row" style="margin-bottom:14px"><span class="bd-chip">${esc(a.type)} · v${a.version}</span><span class="bd-muted">${esc(project())}</span></div>${body}${a.type==='HTML'||a.type==='SVG'?'<details class="bd-spaced"><summary>Исходный код экспортируемого примера</summary><p class="bd-muted">Код отображается как текст; JavaScript здесь не выполняется.</p><pre data-language="'+(a.type==='HTML'?'html':'xml')+'">'+esc(a.type==='HTML'?artifactHtmlSource(a):captureSvg(state().captures.find(c=>c.id===a.captureId)||{name:a.title,size:'1000 × 600'}))+'</pre></details>':''}`,[{label:'Обсудить с агентом',fn:()=>{closeDialog();ask('Проверь материал «'+a.title+'» версии '+a.version+' и предложи улучшения.')}},{label:'Изменить',fn:()=>editText('Редактировать материал',artifactContent(a),text=>{a.history||=[];a.history.unshift({version:a.version,content:artifactContent(a),title:a.title});a.content=text;a.version++},artifactLanguage(a))},{label:'Экспорт',primary:true,fn:()=>exportArtifact(a)}],d=>{$('[data-bd="page-primary"]',d)?.addEventListener('click',e=>{e.currentTarget.textContent='Заказ открыт · демо'});$('[data-bd="page-secondary"]',d)?.addEventListener('click',e=>{e.currentTarget.textContent='Квитанция и история доступны'})});}
  function artifactHtmlSource(a){return '<!doctype html><html lang="ru"><meta charset="utf-8"><title>'+esc(a.title)+'</title><style>body{font:16px system-ui;background:#f5f6f4;color:#242824;margin:48px}h1{font-size:36px}article{max-width:760px}button{padding:12px 18px;background:#344c3b;color:white;border:0;border-radius:7px}p{line-height:1.6;color:#667064}</style><article><small>ORIGINAL PROTOTYPE · NOT PRODUCTION</small><h1>'+esc(a.title)+'</h1><p>'+esc(a.content||taskState().brief)+'</p><button onclick="this.textContent=\'Демонстрация результата\'">Посмотреть результат</button></article></html>'}
  function exportArtifact(a){if(a.type==='SVG'){download('artifact.svg',captureSvg(state().captures.find(c=>c.id===a.captureId)||{name:a.title,size:'1000 × 600'}),'image/svg+xml');return}if(a.type==='HTML'){download('prototype.html',artifactHtmlSource(a),'text/html');return}download(a.type==='Markdown'?'artifact.md':'artifact.txt',artifactContent(a));}
  function artifactMenu(id){const a=taskState().artifacts.find(x=>x.id===id);if(!a)return;menu(a.title,[{label:'Переименовать',fn:()=>editText('Название материала',a.title,t=>a.title=t)},{label:'Версии',fn:()=>artifactVersions(a)},{label:a.archived?'Восстановить':'В архив',fn:()=>{a.archived=!a.archived;save();renderDesign()}},{label:'Экспорт',fn:()=>exportArtifact(a)}])}
  function artifactVersions(a){modal('Версии: '+a.title,`<p><b>v${a.version}</b> · текущая</p>${(a.history||[]).map((v,i)=>`<section class="bd-box" style="margin-top:8px"><div class="bd-row"><b class="bd-grow">v${v.version}</b><button class="btn soft" data-restore-artifact="${i}">Восстановить как новую</button></div><pre data-language="${esc(artifactLanguage({...a,title:v.title||a.title}))}">${esc(v.content.slice(0,650))}</pre></section>`).join('')||'<p class="bd-muted">Нет сохранённых предыдущих версий. Они появятся после редактирования.</p>'}`,[],d=>$$('[data-restore-artifact]',d).forEach(b=>b.onclick=()=>{const old=a.history[+b.dataset.restoreArtifact];a.history.unshift({version:a.version,content:artifactContent(a),title:a.title});a.content=old.content;a.version++;save();closeDialog();renderDesign();openArtifact(a.id)}))}
  function newArtifact(){modal('Создать материал','<label><span>Название</span><input id="bdArtifactTitle" placeholder="Например, описание функциональности"></label><label><span>Формат</span><select id="bdArtifactType"><option value="Markdown">Markdown</option><option value="HTML">Интерактивный макет HTML</option><option value="Document">Документ</option><option value="SVG">Изображение SVG</option></select></label><div id="bdArtifactError" class="bd-error"></div>',[{label:'Создать',primary:true,fn:d=>{const title=$('#bdArtifactTitle',d).value.trim();if(!title){$('#bdArtifactError',d).textContent='Введите название.';return}const a={id:uid(),title,type:$('#bdArtifactType',d).value,version:1,archived:false};taskState().artifacts.unshift(a);save();closeDialog();renderDesign();openArtifact(a.id)}}])}
  function componentDialog(id){const c=components.find(x=>x[0]===id);if(!c)return;modal(c[1],`<div class="bd-row"><span class="bd-chip">${esc(c[2])}</span><span class="bd-muted">Контракт + интерактивное превью</span></div><label class="bd-spaced"><span>Состояние</span><select id="bdComponentState"><option value="default">Default</option><option value="hover">Hover</option><option value="focus">Focus</option><option value="disabled">Disabled</option><option value="loading">Loading</option><option value="error">Error</option></select></label><div class="bd-box" id="bdComponentPreview" style="min-height:95px;display:grid;place-items:center;margin-bottom:12px"></div><details><summary>Использование и доступность</summary><pre data-language="text">${esc(componentContract(c))}</pre><h3>Структура контракта · пример</h3><pre data-language="json">${esc(JSON.stringify({component:c[0],category:c[2],states:['default','hover','focus-visible','disabled','loading','error'],sizes:{compact:32,normal:40,touch:44},themes:['light','dark','corporate']},null,2))}</pre><h3>Фрагмент макета · HTML</h3><pre data-language="html">${esc(c[3])}</pre><p class="bd-muted">Это иллюстрация, не API установленной библиотеки.</p></details><p class="bd-muted">Превью локальное. Полный API и адаптеры берутся из проверенной версии библиотеки после реализации.</p>`,[{label:'Передать агенту',fn:()=>{closeDialog();ask('Используй компонент «'+c[1]+'» из корпоративного UI Kit. Проверь доступность, все состояния и адаптивность перед переносом.')}},{label:'Скачать контракт',primary:true,fn:()=>download(c[0]+'.contract.txt',componentContract(c))}],d=>{const draw=()=>{const v=$('#bdComponentState',d).value,p=$('#bdComponentPreview',d);let html=c[3];if(id==='button')html=`<button class="btn primary" ${v==='disabled'||v==='loading'?'disabled':''} id="bdDemoComponentButton">${v==='loading'?'Выполняется…':v==='error'?'Повторить':'Продолжить'}</button>`;if(id==='field')html=`<label style="width:100%"><span>Название</span><input ${v==='disabled'?'disabled':''} placeholder="Название проекта" aria-invalid="${v==='error'}" style="width:100%">${v==='error'?'<small class="bd-error">Укажите название проекта</small>':''}</label>`;if(id==='select')html=`<select aria-label="Стенд" ${v==='disabled'?'disabled':''}><option>ДЕВ</option><option>ИФТ</option></select>`;if(id==='question')html='<div><p>Какой вариант использовать?</p><label class="bd-inline-label"><input type="radio" name="bdPreviewAnswer" checked>Предложенный</label><label class="bd-inline-label"><input type="radio" name="bdPreviewAnswer">Свой ответ</label><input placeholder="Введите свой ответ" aria-label="Свой ответ"></div>';if(id==='tabs')html='<div class="bd-row"><button class="btn primary" data-bd-demo-tab="Обзор">Обзор</button><button class="btn ghost" data-bd-demo-tab="История">История</button></div><p id="bdDemoTabContent">Обзор компонента</p>';if(id==='empty')html='<div style="text-align:center"><b>Нет подключений</b><p class="bd-muted">Добавьте первое подключение, чтобы начать.</p><button class="btn soft" id="bdDemoComponentButton">Добавить</button></div>';if(id==='dialog')html='<div><h3>Изменения готовы</h3><p>Сохранить локальный черновик?</p><button class="btn primary" id="bdDemoComponentButton">Сохранить</button></div>';p.innerHTML=html;labelForms(p);p.style.opacity=v==='disabled'?'.5':'1';p.style.outline=v==='focus'?'2px solid var(--mint)':'';p.style.background=v==='hover'?'var(--hover)':'';$('#bdDemoComponentButton',p)?.addEventListener('click',e=>{e.currentTarget.textContent='Готово · демо'});$$('[data-bd-demo-tab]',p).forEach(b=>b.onclick=()=>{$$('[data-bd-demo-tab]',p).forEach(t=>t.className='btn ghost');b.className='btn primary';$('#bdDemoTabContent',p).textContent=b.dataset.bdDemoTab+' компонента'})};$('#bdComponentState',d).onchange=draw;draw()})}
  function componentContract(c){return `${c[1]} (${c[0]})\nКатегория: ${c[2]}\n\nСостояния: default, hover, focus-visible, disabled, loading, error.\nРазмеры: compact 32px, normal 40px, touch 44px.\nТема: semantic tokens, light / dark / corporate.\nДоступность: имя элемента, видимый фокус, клавиатура, aria-state.\nТекст: длинные значения не ломают контейнер.\nДанные: нет жёстко заданных учётных данных или серверов.\n\nПрототип контракта, не установленный пакет.`}
  function tokenDialog(){const tokens=[['surface.canvas','#181b19'],['surface.panel','#1f2320'],['text.primary','#eff3ec'],['action.primary','#cdd5ca'],['status.info','#9fb7c8'],['status.danger','#dfa5a8']];modal('Токены и темы',`<div class="bd-swatchrow">${tokens.map(([n,v])=>`<div class="bd-swatch"><i style="background:${v}"></i><b>${n}</b><span>${v}</span></div>`).join('')}</div><p class="bd-muted">Семантические имена отделены от цветов. Для корпоративного варианта переопределяются токены, структура компонентов сохраняется.</p><pre data-language="json">${esc(JSON.stringify(Object.fromEntries(tokens),null,2))}</pre><details><summary>CSS-представление</summary><pre data-language="css">${esc(':root {\n'+tokens.map(([n,v])=>'  --'+n.replaceAll('.','-')+': '+v+';').join('\n')+'\n}')}</pre></details>`,[{label:'Экспорт JSON',primary:true,fn:()=>download('semantic.tokens.json',JSON.stringify(Object.fromEntries(tokens),null,2),'application/json')}])}
